<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include<algorithm>
#include<iostream>
#include<cstring>
#include<cstdio>
using namespace std;
#define MOD 1000000007
#define inc(a,b) ((a+b>=MOD)?(a+b-MOD):(a+b))
#define dec(a,b) ((a>=b)?(a-b):(a+MOD-b))
#define mul(a,b) (1LL*(a)*(b)%MOD)
#define updata(x,y) x=inc(x,y)

int power(int x, int k) {
    int res = 1;
    while(k) { if(k&1) res = mul(res,x); x = mul(x,x); k >>= 1; }
    return res;
}

const int maxn = 8;
const int SZ = 1048576 + 5;

int n, a[maxn][maxn], inv100, edges[maxn][maxn], prob[SZ], tripleMask[7][7][7], all, Ans;

inline bool check(int x, int y, int z) {
    int pos[4], lis[4];
    lis[1]=x; lis[2]=y; lis[3]=z;
    for(int i=1;i<=3;i++) pos[i]=i;
    do {
        bool ok = true;
        for(int i=1;i<=3;i++) if(!edges[pos[i]][lis[i]]) { ok=false; break; }
        if(ok) return true;
    } while(next_permutation(pos+1,pos+4));
    return false;
}

void dfs1(int now, int x, int y) {
    if(!now) return;
    if(x == 4) {
        bool used[7];
        for(int i=1;i<=6;i++) used[i]=true;
        int sta = 0;
        for(int i=1;i<=6;i++) {
            for(int j=i+1;j<=6;j++) {
                for(int k=j+1;k<=6;k++) {
                    if(check(i,j,k)) {
                        used[i]=used[j]=used[k]=false;
                        int X=-1,Y=-1,Z=-1;
                        for(int l=1;l<=6;l++) if(used[l]) {
                            if(X==-1) X=l;
                            else if(Y==-1) Y=l;
                            else Z=l;
                        }
                        used[i]=used[j]=used[k]=true;
                        if(Z==-1) continue;
                        sta |= tripleMask[X][Y][Z];
                    }
                }
            }
        }
        updata(prob[sta], now);
        return;
    }
    edges[x][y] = 1; int nxt = mul(now, a[x][y]);
    (y==6) ? dfs1(nxt, x+1, 1) : dfs1(nxt, x, y+1);
    edges[x][y] = 0; nxt = mul(now, dec(1, a[x][y]));
    (y==6) ? dfs1(nxt, x+1, 1) : dfs1(nxt, x, y+1);
}

void dfs2(int now, int x, int y) {
    if(!now) return;
    if(x == 7) {
        int sta = 0;
        for(int i=1;i<=6;i++) {
            for(int j=i+1;j<=6;j++) {
                for(int k=j+1;k<=6;k++) {
                    if(check(i,j,k)) sta |= tripleMask[i][j][k];
                }
            }
        }
        updata(Ans, mul(now, prob[all ^ sta]));
        return;
    }
    edges[x-3][y] = 1; int nxt = mul(now, a[x][y]);
    (y==6) ? dfs2(nxt, x+1, 1) : dfs2(nxt, x, y+1);
    edges[x-3][y] = 0; nxt = mul(now, dec(1, a[x][y]));
    (y==6) ? dfs2(nxt, x+1, 1) : dfs2(nxt, x, y+1);
}

int main() {
    scanf("%d", &n);
    inv100 = power(100, MOD-2);
    for(int i=1;i<=n;i++) for(int j=1;j<=n;j++) { scanf("%d", &a[i][j]); a[i][j] = mul(a[i][j], inv100); }
    for(int i=n+1;i<=6;i++) a[i][i] = 1;
    int cnt = 0;
    for(int i=1;i<=6;i++) for(int j=i+1;j<=6;j++) for(int k=j+1;k<=6;k++) {
        tripleMask[i][j][k] = 1 << cnt;
        cnt++;
    }
    all = (1 << cnt) - 1;
    dfs1(1, 1, 1);
    for(int j=0;j<cnt;j++) {
        for(int i=0;i<(1<<cnt);i++) {
            if(i & (1<<j)) updata(prob[i], prob[i ^ (1<<j)]);
        }
    }
    Ans = 0;
    dfs2(1, 4, 1);
    Ans = dec(1, Ans);
    printf("%d\n", Ans);
    return 0;
}
